parameters.jsCode:
// Извлекаем код-слово из текста сообщения. Сравниваем с активными
// code-words проекта (можно подгрузить из MarkVision через REST или
// просто захардкодить список регулярок).
const text = ($input.item.json.text || '').toLowerCase().trim();
const CODEWORDS = ($env.IG_CODEWORDS || 'smile,promo').split(',').map(s => s.trim().toLowerCase());
const match = CODEWORDS.find(cw => text.split(/[^a-zа-я0-9_]+/).includes(cw));

return {
  json: {
    ...$input.item.json,
    matched_codeword: match || null,
  }
};

parameters.jsonBody:
={{ JSON.stringify({
  token: $env.MARKVISION_INTAKE_TOKEN,
  event_type: 'codeword_dm',
  ig_handle: $env.IG_HANDLE,
  codeword: $json.matched_codeword,
  username: $json.from && $json.from.username ? '@' + $json.from.username : null,
  contact: $json.from && $json.from.phone ? $json.from.phone : null,
  reel_url: $json.story && $json.story.permalink ? $json.story.permalink : null,
  reel_id: $json.story && $json.story.id ? $json.story.id : null,
  external_event_id: $json.id,
  occurred_at: $json.created_time,
  payload: { raw_text: $json.text }
}) }}

={{ JSON.stringify({
  recipient_username: $json.from && $json.from.username ? $json.from.username : null,
  text: 'Лови ссылку: ' + $env.MARKVISION_SUPABASE_URL + '/functions/v1/ig-organic-redirect?c=' + ($env.SHORT_ID_PREFIX || '') + ($json.matched_codeword || '') + '&u=' + encodeURIComponent($json.from && $json.from.username ? $json.from.username : 'anon')
}) }}
